const getCompanyId = () => {
  try { return JSON.parse(localStorage.getItem("company_data") || "{}").company_id || ""; } catch { return ""; }
};
const todayIndia = () => new Intl.DateTimeFormat("en-CA", { timeZone: "Asia/Kolkata", year: "numeric", month: "2-digit", day: "2-digit" }).format(new Date());
const money = (value: unknown) => `₹${(Number(value) || 0).toLocaleString("en-IN", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
const formatDate = (value?: string) => value ? new Date(`${value.slice(0, 10)}T00:00:00Z`).toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric", timeZone: "UTC" }) : "—";
const alertError = (title: string, message?: string) => toast({ title, description: message || "Please try again.", variant: "destructive" });
const fieldClass = "h-10 rounded-xl";
const openWhatsApp = (phone?: string) => {
  const digits = String(phone || "").replace(/\D/g, "");
  if (!digits) { alertError("WhatsApp number is unavailable"); return; }
  const internationalNumber = digits.length === 10 ? `91${digits}` : digits;
  window.open(`https://web.whatsapp.com/send?phone=${internationalNumber}`, "_blank", "noopener,noreferrer");
};

